pts=[(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)]
g=[[8]*8 for _ in range(30)]
for r,c in pts:g[r][c]=7
for orient in ('row','col'):
 groups={}
 for r,c in pts: groups.setdefault(r if orient=='row' else c,[]).append((r,c))
 for grp in groups.values():
  grp.sort(key=lambda p:p[1] if orient=='row' else p[0])
  for (r1,c1),(r2,c2) in zip(grp,grp[1:]):
   if orient=='row':
    for c in range(c1+1,c2):g[r1][c]=3
   else:
    for r in range(r1+1,r2):g[r][c1]=3
print(g)
